// Original AXWG.ReadFrom (0x1ce6be0) calls the protocol's ordinary ReadFrom
// slot. auth_chain's autogenerated slot (0x1cde380) promotes raw PacketConn,
// so this entry must not be silently rerouted to authenticated ReadFromUID.
func TestNativeSSRPacketOrdinaryInterfaceDispatch(t *testing.T) {
	for _, protocol := range []string{"origin", "auth_chain_a"} {
		client, server := packetPair(t)
		info, _ := wrapperInfo(t, 0)
		info.C8Qsa8G8XMw0 = H.Mu0vMIIs(protocol)
		c, err := INOdx8(server, info)
		if err != nil {
			t.Fatal(err)
		}
		defer c.Free()
		if c.GetServerInfo() != info {
			t.Fatal("server-info identity")
		}
		wire := []byte("unauthenticated raw datagram")
		if _, err = client.WriteTo(wire, server.LocalAddr()); err != nil {
			t.Fatal(err)
		}
		dst := make([]byte, 128)
		n, src, err := c.ReadFrom(dst)
		if err != nil || !bytes.Equal(dst[:n], wire) || src.String() != client.LocalAddr().String() {
			t.Fatal(n, src, err)
		}
		if protocol == "origin" {
			if n, err = c.WriteTo(wire, src); n != len(wire) || err != nil {
				t.Fatal(n, err)
			}
			n, _, err = client.ReadFrom(dst)
			if err != nil || !bytes.Equal(dst[:n], wire) {
				t.Fatal(n, err)
			}
		} else {
			var panicValue any
			func() { defer func() { panicValue = recover() }(); c.WriteTo(wire, src) }()
			if panicValue != "please use WriteToUID()" {
				t.Fatalf("panic=%v", panicValue)
			}
			// Original 0x1ce6aa0 has explicit Unlock after the interface call, not
			// a defer. Do not turn this original panic path into a recovered success.
			if c.TryLock() {
				c.Unlock()
				t.Fatal("original panic must retain lock")
			}
			c.Unlock() // Test cleanup only.
		}
	}
}

func TestNativeSSRPacketUnknownUID(t *testing.T) {
	client, server := packetPair(t)
	info, _ := wrapperInfo(t, 2)
	info.N3pMXuwX85c = new(M.GTFAWF[int64, *U.LJJkaD])
	c, err := INOdx8(server, info)
	if err != nil {
		t.Fatal(err)
	}
	defer c.Free()
	wire := append(bytes.Clone(addressFixture), []byte("payload")...)
	client.WriteTo(wire, server.LocalAddr())
	dst := make([]byte, 128)
	n, user, src, target, err := c.ReadFromProxy(dst)
	if n != 0 || user != nil || src == nil || target != nil || err != nil {
		t.Fatal(n, user, src, target, err)
	}
	if string(dst[:7]) != "payload" {
		t.Fatal("parse/copy must occur before UID lookup")
	}
}
